/**
 * Stub of `@deepseek-ai/dsh-compaction-basic`.
 *
 * A recording stand-in for the shipped `BasicCompactionEngine`: every call the
 * doctor delegates back to the shipped backend lands in `this.calls`, so a test
 * can prove *which* path ran and *what scale* the shipped path observed.
 *
 * `config.__test` drives the switches (never a real config key).
 */

import { ManualCompactionError } from "@deepseek-ai/dsh-compaction";

export class BasicCompactionEngine {
  static inject = ["llm", "tokenMeter", "sessions"];

  constructor(ctx, config = {}) {
    this.ctx = ctx;
    this.config = config;
    this.options = (config !== null && typeof config === "object" ? config.__test : undefined) ?? {};
    this.calls = { summarize: [], compactIfNeeded: [], compactRegion: [], compactNow: [] };
  }

  async summarize(input, agent, signal) {
    const count = Array.isArray(input?.messages) ? input.messages.length : 0;
    this.calls.summarize.push({ count, bytes: JSON.stringify(input?.messages ?? []).length });
    if (this.options.throwingSummarize === true) throw new Error("base summarize exploded");
    return {
      blocks: [{ type: "text", text: `SUMMARY(${count})` }],
      usage: { inputTokens: 10, outputTokens: 4, totalTokens: 14 },
    };
  }

  async compactIfNeeded(agent, trigger, signal) {
    // The shipped path prices the surface itself — this is exactly where the
    // scale defect shows up, so the stub records what it was handed.
    const measurement = this.ctx?.tokenMeter?.measure?.(agent?.session);
    this.calls.compactIfNeeded.push({ trigger, measurement });
    if (this.options.advanceGeneration === true && agent?.session?.surface !== undefined) {
      agent.session.surface.replaceGeneration += 1;
    }
    return { via: "base", trigger, surfaceTokens: measurement?.surfaceTokens };
  }

  async compactRegion(start, end, agent, signal) {
    this.calls.compactRegion.push({ start, end });
    return { via: "region", start, end };
  }

  async compactNow(agent, signal, sourceCommandId) {
    this.calls.compactNow.push({ sourceCommandId });
    if (this.options.throwingManual === true) {
      throw new ManualCompactionError("busy", "manual compaction requires an idle agent with no waking queued work");
    }
    return { via: "now" };
  }
}

export default { BasicCompactionEngine };
